html:
{%- set project = doc -%}
{%- set client = frappe.get_doc("ClientProfile", project.client) -%}
{%- set client_email = frappe.db.get_value("User", client.user, "email") if client.user else None -%}
{%- set generated_at = frappe.utils.now_datetime().strftime("%d/%m/%Y à %H:%M") -%}
{%- set description_text = frappe.utils.strip_html(project.description or "") -%}
{%- set deliverables_text = project.deliverables or "" -%}
{%- set exclusions_text = project.exclusions or "" -%}
{%- set deadlines_text = project.deadlines or "" -%}
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Cahier des Charges — {{ project.title }}</title>
<style>
	body { font-family: "Helvetica Neue", Arial, sans-serif; color: #1f2933; font-size: 13px; margin: 0; padding: 24px; background: #f5f6f8; }
	.page { max-width: 680px; margin: 0 auto; background: #ffffff; border: 1px solid #d2d6dc; border-radius: 10px; padding: 32px; }
	.icon-badge { width: 34px; height: 34px; border: 1px solid #1f2933; border-radius: 8px;
		display: flex; align-items: center; justify-content: center; margin: 0 auto 14px auto;
		font-size: 15px; font-weight: bold; }
	.kicker { text-align: center; font-size: 10.5px; text-transform: uppercase; letter-spacing: 0.14em; color: #616e7c; margin: 0 0 6px 0; }
	h1 { text-align: center; font-size: 24px; margin: 0 0 10px 0; }
	.accent-line { width: 46px; height: 3px; background: #1f2933; margin: 0 auto 26px auto; border-radius: 2px; }

	.info-card { border: 1px solid #e4e7eb; border-radius: 8px; padding: 16px 18px; margin-bottom: 22px; }
	table.info { width: 100%; border-collapse: collapse; }
	table.info td { padding: 7px 8px 7px 0; vertical-align: top; width: 50%; }
	.field-label { display: block; font-size: 10.5px; font-weight: bold; color: #1f2933; }
	.field-label::before { content: "| "; color: #9aa5b1; }
	.field-value { display: block; margin-top: 2px; color: #3e4c59; font-size: 12.5px; }

	.section-title { display: flex; align-items: center; gap: 7px; font-size: 11.5px; font-weight: bold;
		text-transform: uppercase; letter-spacing: 0.05em; color: #1f2933; margin: 22px 0 4px 0; }
	.section-title .dot { width: 6px; height: 6px; border-radius: 50%; background: #1f2933; display: inline-block; }
	.sub-label { font-size: 11px; color: #616e7c; margin: 0 0 8px 0; }

	.perimeter-card { border: 1px solid #e4e7eb; border-radius: 8px; overflow: hidden; margin-top: 4px; }
	.sub-band { background: #1f2933; color: #ffffff; font-size: 10px; font-weight: bold;
		text-transform: uppercase; letter-spacing: 0.06em; padding: 6px 12px; }
	.sub-band.alt { background: #e4e7eb; color: #1f2933; }
	.block { padding: 12px; font-size: 12.5px; }
	.block + .sub-band { border-top: 1px solid #e4e7eb; }
	.description { white-space: pre-wrap; line-height: 1.55; }

	.footer { margin-top: 28px; padding-top: 12px; border-top: 1px solid #e4e7eb; color: #9aa5b1; font-size: 10.5px; text-align: center; }
</style>
</head>
<body>
<div class="page">
	<div class="icon-badge">📄</div>
	<p class="kicker">Cahier des charges</p>
	<h1>{{ client.company_name or "Nom de l'entreprise" }}</h1>
	<div class="accent-line"></div>

	<div class="info-card">
		<table class="info">
			<tr>
				<td>
					<span class="field-label">Budget / Projet</span>
					<span class="field-value">
						{%- if project.budget_min or project.budget_max -%}
							{{ "%d"|format(project.budget_min) if project.budget_min else "?" }} € — {{ "%d"|format(project.budget_max) if project.budget_max else "?" }} €
						{%- else -%}
							À définir
						{%- endif -%}
					</span>
				</td>
				<td>
					<span class="field-label">Numéro de téléphone</span>
					<span class="field-value">{{ client.phone or "—" }}</span>
				</td>
			</tr>
			<tr>
				<td>
					<span class="field-label">Adresse e-mail</span>
					<span class="field-value">{{ client_email or "—" }}</span>
				</td>
				<td>
					<span class="field-label">Adresse postale de l'entreprise</span>
					<span class="field-value">{{ client.country or "—" }}</span>
				</td>
			</tr>
			<tr>
				<td colspan="2">
					<span class="field-label">Localisation du projet</span>
					<span class="field-value">{{ project.location or "—" }}</span>
				</td>
			</tr>
			<tr>
				<td>
					<span class="field-label">Auteur</span>
					<span class="field-value">{{ (client.first_name or "") ~ " " ~ (client.last_name or "") }}</span>
				</td>
				<td>
					<span class="field-label">Date</span>
					<span class="field-value">{{ generated_at }}</span>
				</td>
			</tr>
		</table>
	</div>

	<p class="section-title"><span class="dot"></span> Vue d'ensemble</p>
	<p class="sub-label">But / Objectifs du projet</p>
	<div class="info-card" style="margin-top: 0;">
		<div class="description">{{ description_text or "Aucune description fournie." }}</div>
	</div>

	<p class="section-title"><span class="dot"></span> Périmètre du projet</p>
	<div class="perimeter-card">
		<p class="sub-band">Livrables</p>
		<div class="block description">{{ deliverables_text or "Non précisé." }}</div>
		<p class="sub-band alt">Exclusions</p>
		<div class="block description">{{ exclusions_text or "Non précisé." }}</div>
		<p class="sub-band">Échéances</p>
		<div class="block description">{{ deadlines_text or "Non précisé." }}</div>
	</div>

	<div class="footer">
		Document généré le {{ generated_at }} — Cahier des Charges n°{{ project.name }}
	</div>
</div>
</body>
</html>
